import java.util.*;

public class Main {
    int subarrayBitwiseORs(int[] arr) {
        Set<Integer> current = new HashSet<>();                                   // every distinct OR value achievable by a subarray ENDING here
        Set<Integer> result = new HashSet<>();                                   // every distinct OR value seen across the whole array so far
        for (int x : arr) {
            Set<Integer> next = new HashSet<>();
            next.add(x);
            for (int prev : current) next.add(prev | x);                          // extend every previous ending value, plus start fresh with just x
            current = next;
            result.addAll(current);
        }
        return result.size();
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(solution.subarrayBitwiseORs(new int[]{1, 2, 4}));
    }
}

