#include <bits/stdc++.h>
using namespace std;

int subarrayBitwiseORs(vector<int>& arr) {
    unordered_set<int> current;                                                // every distinct OR value achievable by a subarray ENDING here
    unordered_set<int> result;                                                // every distinct OR value seen across the whole array so far
    for (int x : arr) {
        unordered_set<int> next;
        next.insert(x);
        for (int prev : current) next.insert(prev | x);                         // extend every previous ending value, plus start fresh with just x
        current = next;
        for (int v : current) result.insert(v);
    }
    return (int)result.size();
}

int main() {
    vector<int> arr = {1, 2, 4};
    cout << subarrayBitwiseORs(arr) << endl;
    return 0;
}
